use std::collections::HashMap;impl Solution{pub fn find_substring(s:String,w:Vec<String>)->Vec<i32>{if w.is_empty(){return vec![]}let l=w[0].len();let k=w.len();let mut need=HashMap::new();for x in &w{*need.entry(x.as_str()).or_insert(0)+=1;}let mut o=vec![];for off in 0..l{let(mut left,mut c)=(off,0);let mut have:HashMap<&str,i32>=HashMap::new();let mut r=off;while r+l<=s.len(){let x=&s[r..r+l];if !need.contains_key(x){have.clear();c=0;left=r+l;}else{*have.entry(x).or_insert(0)+=1;c+=1;while have[x]>need[x]{let y=&s[left..left+l];*have.get_mut(y).unwrap()-=1;left+=l;c-=1;}if c==k{ o.push(left as i32);let y=&s[left..left+l];*have.get_mut(y).unwrap()-=1;left+=l;c-=1;}}r+=l;}}o}}
